28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be valid E.164")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private java.time.LocalDate registrationDate;
61	
62	    @Column(name = "birth_date", columnDefinition = "DATE")
63	    private java.time.LocalDate birthDate;
64	
65	    public java.time.LocalDate getBirthDate() {
66	        return this.birthDate;
67	    }
68	
69	    public void setBirthDate(java.time.LocalDate birthDate) {
70	        this.birthDate = birthDate;
71	    }
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_member_count")
83	    private Integer householdMemberCount;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    public Integer getPossibleDuplicateOf() {
89	        return this.possibleDuplicateOf;
90	    }
91	
92	    /** Record the id of an existing owner this one is a possible (soft) duplicate of, or null. */
93	    public void assignPossibleDuplicate(Collection<Owner> existingOwners) {
94	        this.possibleDuplicateOf = org.springframework.samples.petclinic.util.PossibleDuplicates.matchIn(this, existingOwners);
95	    }
96	
97	    public String getCustomerCode() {
98	        return this.customerCode;
99	    }
100	
101	    public Integer getNamesakeCount() {
102	        return this.namesakeCount;
103	    }
104	
105	    public void setNamesakeCount(Integer namesakeCount) {
106	        this.namesakeCount = namesakeCount;
107	    }
108	
109	    /** Record how many of {@code existingOwners} share this owner's first and last name, case-insensitively. */
110	    public void assignNamesakeCount(Collection<Owner> existingOwners) {
111	        int count = 0;
112	        for (Owner other : existingOwners) {
113	            if (getFirstName().equalsIgnoreCase(other.getFirstName())
114	                && getLastName().equalsIgnoreCase(other.getLastName())) {
115	                count++;
116	            }
117	        }
118	        this.namesakeCount = count;
119	        assignHouseholdMemberCount(existingOwners);
120	    }
121	
122	    public Integer getHouseholdMemberCount() {
123	        return this.householdMemberCount;
124	    }
125	
126	    /** Record how many owners (this one included) share this owner's household after this create. */
127	    public void assignHouseholdMemberCount(Collection<Owner> existingOwners) {
128	        int count = 1;
129	        for (Owner other : existingOwners) {
130	            if (householdId != null && householdId.equals(other.getHouseholdId())) {
131	                count++;
132	            }
133	        }
134	        this.householdMemberCount = count;
135	    }
136	
137	    public String getHouseholdId() {
138	        return this.householdId;
139	    }
140	
141	    public void setHouseholdId(String householdId) {
142	        this.householdId = householdId;
143	    }
144	
145	    /** Assign the '<REGION>-<HASH8>' customer code: region from the postcode, HASH8 from telephone+lastName. */
146	    public void assignCustomerCode(int cityCount) {
147	        this.customerCode = CustomerCodes.build(getCity(), getPostcode(), getTelephone(), getLastName());
148	    }
149	
150	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
151	    private Set<Pet> pets;
152	
153	    public java.time.LocalDate getRegistrationDate() {
154	        return this.registrationDate;
155	    }
156	
157	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
158	        this.registrationDate = registrationDate;
159	    }
160	
161	    public String getAddress() {
162	        return this.address;
163	    }
164	
165	    /** Store the address normalized so create persists and returns the canonical form. */
166	    public void setAddress(String address) {
167	        this.address = AddressNormalizer.normalize(address);
168	    }
169	
170	    public String getCity() {
171	        return this.city;
172	    }
173	
174	    public void setCity(String city) {
175	        this.city = city;
176	    }
177	
178	    public String getTelephone() {
179	        return this.telephone;
180	    }
181	
182	    /** Store the telephone in E.164 form so create and update persist and return it normalized. */
183	    public void setTelephone(String telephone) {
184	        this.telephone = TelephoneNormalizer.toE164(telephone);
185	    }
186	
187	    public String getPostcode() {
188	        return this.postcode;
189	    }
190	
191	    public void setPostcode(String postcode) {
192	        this.postcode = postcode;
193	    }
194	
195	    public String getEmail() {
196	        return this.email;
197	    }
198	
199	    /** Store the address lower-cased so it is persisted and returned normalized. */
200	    public void setEmail(String email) {
201	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
202	    }
203	
204	    protected Set<Pet> getPetsInternal() {
205	        if (this.pets == null) {
206	            this.pets = new HashSet<>();
207	        }
208	        return this.pets;
209	    }
210	
211	    protected void setPetsInternal(Set<Pet> pets) {
212	        this.pets = pets;
213	    }
214	
215	    public List<Pet> getPets() {
216	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
217	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
218	        return Collections.unmodifiableList(sortedPets);
219	    }
220	
221	    public void setPets(List<Pet> pets) {
222	        this.pets = new HashSet<>(pets);
223	    }
224	
225	    public void addPet(Pet pet) {
226	        getPetsInternal().add(pet);
227	        pet.setOwner(this);
228	    }
229	
230	    /**
231	     * Return the Pet with the given name, or null if none found for this Owner.
232	     *
233	     * @param name to test
234	     * @return true if pet name is already in use
235	     */
236	    public Pet getPet(String name) {
237	        return getPet(name, false);
238	    }
239	
240	    /**
241	     * Return the Pet with the given name, or null if none found for this Owner.
242	     *
243	     * @param name to test
244	     * @return true if pet name is already in use
245	     */
246	    public Pet getPet(String name, boolean ignoreNew) {
247	        name = name.toLowerCase();
248	        for (Pet pet : getPetsInternal()) {
249	            if (!ignoreNew || !pet.isNew()) {
250	                String compName = pet.getName();
251	                compName = compName.toLowerCase();
252	                if (compName.equals(name)) {
253	                    return pet;
254	                }
255	            }
256	        }
257	        return null;
258	    }
259	
260	    public Pet getPet(Integer petId) {
261	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
262	    }
263	
264	    @Override
265	    public String toString() {
266	        return new ToStringCreator(this)
267	
268	            .append("id", this.getId())
269	            .append("new", this.isNew())
270	            .append("lastName", this.getLastName())
271	            .append("firstName", this.getFirstName())
272	            .append("address", this.address)
273	            .append("city", this.city)
274	            .append("telephone", this.telephone)
275	            .toString();
276	    }
277	}
