33	/**
34	 * Flags every owner response with {@code bulkSignupWarning}: true once more than 80 owners
35	 * have already been created today (by registrationDate), otherwise false. Purely informational,
36	 * so unlike the daily-limit rule it never rejects a request.
37	 */
38	@ControllerAdvice
39	public class OwnerBulkSignupAdvice implements ResponseBodyAdvice<Object> {
40	
41	    private static final int BULK_SIGNUP_THRESHOLD = 80;
42	
43	    private final ClinicService clinicService;
44	
45	    public OwnerBulkSignupAdvice(ClinicService clinicService) {
46	        this.clinicService = clinicService;
47	    }
48	
49	    @Override
50	    public boolean supports(MethodParameter returnType,
51	                            Class<? extends HttpMessageConverter<?>> converterType) {
52	        return true;
53	    }
54	
55	    @Override
56	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
57	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
58	                                  ServerHttpRequest request, ServerHttpResponse response) {
59	        if (body instanceof OwnerDto owner) {
60	            owner.setBulkSignupWarning(createdTodayCount() > BULK_SIGNUP_THRESHOLD);
61	        }
62	        return body;
63	    }
64	
65	    private int createdTodayCount() {
66	        LocalDate today = BusinessDays.toBusinessDay(LocalDate.now());
67	        int count = 0;
68	        for (Owner existing : clinicService.findAllOwners()) {
69	            if (today.equals(existing.getRegistrationDate())) {
70	                count++;
71	            }
72	        }
73	        return count;
74	    }
