69	            throw new WrongTelephoneLengthException();
70	        }
71	        return body;
72	    }
73	
74	    private boolean hasWrongNationalLength(String telephone) {
75	        for (Map.Entry<String, Integer> rule : NATIONAL_LENGTH.entrySet()) {
76	            if (telephone.startsWith(rule.getKey())) {
77	                return telephone.length() - rule.getKey().length() != rule.getValue();
78	            }
79	        }
80	        return false;
81	    }
82	
83	    @Override
84	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
85	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
86	        return body;
87	    }
88	
89	    @Override
90	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
91	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
92	        return inputMessage;
93	    }
94	
95	    @ExceptionHandler(WrongTelephoneLengthException.class)
96	    @ResponseBody
97	    public ResponseEntity<Void> handleWrongTelephoneLength(WrongTelephoneLengthException e) {
98	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).build();
99	    }
100	
101	    /** Signals that the telephone's national number is the wrong length for its country code. */
102	    static class WrongTelephoneLengthException extends RuntimeException {
103	    }
104	}
