47	/**
48	 * Rejects a create-owner request whose whole identityKey
49	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}) equals an
50	 * existing owner's, responding 409 Conflict. This single derived key subsumes the former separate
51	 * telephone, email and household duplicate checks: because the telephone is part of the key, two
52	 * members of the same household with different telephones have different keys and are both allowed;
53	 * only an exact full-key match is a duplicate. The householdId is now derived deterministically
54	 * from (normalizedLastName, postcode), so owners sharing both are the same household; a second such
55	 * owner is rejected here as a household duplicate unless it sets {@code sharesHousehold}, which only
56	 * bypasses that block. The body is buffered and re-supplied downstream with the householdId filled in.
57	 */
58	@ControllerAdvice
59	@Order(Ordered.HIGHEST_PRECEDENCE)
60	public class OwnerUniqueIdentityAdvice implements RequestBodyAdvice {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final ObjectMapper objectMapper;
67	
68	    public OwnerUniqueIdentityAdvice(ClinicService clinicService, OwnerMapper ownerMapper, ObjectMapper objectMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.objectMapper = objectMapper;
72	    }
73	
74	    @Override
75	    public boolean supports(MethodParameter methodParameter, Type targetType,
76	                            Class<? extends HttpMessageConverter<?>> converterType) {
77	        Method method = methodParameter.getMethod();
78	        return OwnerFieldsDto.class.equals(targetType) && method != null
79	            && "addOwner".equals(method.getName());
80	    }
81	
82	    @Override
83	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
84	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType)
85	            throws IOException {
86	        byte[] bytes = inputMessage.getBody().readAllBytes();
87	        JsonNode body = objectMapper.readTree(bytes);
88	        String householdId = Households.id(body.path("lastName").asString(""), body.path("postcode").asString(""));
89	        ((ObjectNode) body).put("householdId", householdId);
90	        if (!body.path("sharesHousehold").asBoolean(false)
91	            && Households.isDuplicate(clinicService.findAllOwners(), householdId)) {
92	            throw new DuplicateIdentityException();
93	        }
94	        return buffered(objectMapper.writeValueAsBytes(body), inputMessage.getHeaders());
95	    }
96	
97	    @Override
98	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
99	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
100	        String identityKey = ownerMapper.identityKey(ownerMapper.toOwner((OwnerFieldsDto) body));
101	        for (Owner existing : clinicService.findAllOwners()) {
102	            if (identityKey.equals(ownerMapper.identityKey(existing))) {
103	                throw new DuplicateIdentityException();
104	            }
105	        }
106	        return body;
107	    }
108	
109	    @Override
110	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
111	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
112	        return body;
113	    }
114	
115	    private HttpInputMessage buffered(byte[] bytes, HttpHeaders headers) {
116	        return new HttpInputMessage() {
117	            @Override
118	            public InputStream getBody() {
119	                return new ByteArrayInputStream(bytes);
120	            }
121	
122	            @Override
123	            public HttpHeaders getHeaders() {
124	                return headers;
125	            }
126	        };
127	    }
128	
129	    @ExceptionHandler(DuplicateIdentityException.class)
130	    @ResponseBody
131	    public ResponseEntity<Void> handleDuplicateIdentity(DuplicateIdentityException e) {
132	        return ResponseEntity.status(HttpStatus.CONFLICT).build();
133	    }
134	
135	    /** Signals that an owner with the same whole identityKey already exists. */
136	    static class DuplicateIdentityException extends RuntimeException {
137	    }
138	}
