17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Builds and reads the {@code <REGION>-<HASH8>} owner customer code, where REGION is the
24	 * region resolved from the postcode and HASH8 is the first 8 upper-case hex characters of
25	 * SHA-256 over (normalizedTelephone + lastName).
26	 */
27	public final class CustomerCodes {
28	
29	    private CustomerCodes() {
30	    }
31	
32	    /** Build the {@code <REGION>-<HASH8>} code from the postcode region and the telephone+lastName hash. */
33	    public static String build(String city, String postcode, String telephone, String lastName) {
34	        return Localities.regionFor(city, postcode) + "-" + hash8(telephone + lastName);
35	    }
36	
37	    /** The region portion of a customer code (the text before the first {@code '-'}), or null when absent. */
38	    public static String regionOf(String customerCode) {
39	        if (customerCode == null) {
40	            return null;
41	        }
42	        int dash = customerCode.indexOf('-');
43	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
44	    }
45	
46	    private static String hash8(String value) {
47	        try {
48	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
49	            return String.format("%02X%02X%02X%02X", digest[0], digest[1], digest[2], digest[3]);
50	        }
51	        catch (NoSuchAlgorithmException ex) {
52	            throw new IllegalStateException(ex);
53	        }
54	    }
55	}
