16	package org.springframework.samples.petclinic.util;
17	
18	import java.util.Locale;
19	
20	/**
21	 * Normalizes postal addresses to a canonical form.
22	 *
23	 * <p>Surrounding whitespace is trimmed and internal runs collapsed to a single space, the
24	 * text is upper-cased, and common street-type abbreviations are expanded (ST-&gt;STREET,
25	 * RD-&gt;ROAD, AVE-&gt;AVENUE). A blank input normalizes to the empty string, which callers
26	 * treat as a missing required field. Normalization is idempotent, so an already-normalized
27	 * value is returned unchanged, letting create and duplicate detection share one form.
28	 */
29	public final class AddressNormalizer {
30	
31	    private AddressNormalizer() {
32	    }
33	
34	    /** Return {@code address} in canonical form, or {@code null} when it is {@code null}. */
35	    public static String normalize(String address) {
36	        if (address == null) {
37	            return null;
38	        }
39	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
40	        if (collapsed.isEmpty()) {
41	            return "";
42	        }
43	        StringBuilder result = new StringBuilder(collapsed.length());
44	        for (String token : collapsed.split(" ")) {
45	            if (result.length() > 0) {
46	                result.append(' ');
47	            }
48	            result.append(expand(token));
49	        }
50	        return result.toString();
51	    }
52	
53	    private static String expand(String token) {
54	        switch (token) {
55	            case "ST":
56	                return "STREET";
57	            case "RD":
58	                return "ROAD";
59	            case "AVE":
60	                return "AVENUE";
61	            default:
62	                return token;
63	        }
64	    }
65	}
