16	package org.springframework.samples.petclinic.util;
17	
18	import java.util.Map;
19	
20	/**
21	 * Resolves an owner's locality (region) from their city using a fixed lookup table.
22	 *
23	 * <p>The mapping is pinned to Sydney-&gt;NSW, Melbourne-&gt;VIC and Brisbane-&gt;QLD. Any
24	 * city outside the table resolves to {@code UNKNOWN}.
25	 */
26	public final class Localities {
27	
28	    private static final Map<String, String> CITY_REGION =
29	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
30	
31	    /** Region -> inclusive {low, high} 4-digit postcode range. */
32	    private static final Map<String, int[]> REGION_RANGE =
33	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
34	
35	    private Localities() {
36	    }
37	
38	    /** Return the canonical region for {@code city}, or {@code UNKNOWN} when it is not in the table. */
39	    public static String regionFor(String city) {
40	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
41	    }
42	
43	    /** Prefer the region from the postcode range; fall back to the city table when the postcode is absent or unknown. */
44	    public static String regionFor(String city, String postcode) {
45	        String byPostcode = regionForPostcode(postcode);
46	        return byPostcode != null ? byPostcode : regionFor(city);
47	    }
48	
49	    /** Region whose range contains {@code postcode}, or {@code null} when it is absent, malformed, or out of every range. */
50	    private static String regionForPostcode(String postcode) {
51	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
52	            return null;
53	        }
54	        int value = Integer.parseInt(postcode);
55	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
56	            int[] range = entry.getValue();
57	            if (value >= range[0] && value <= range[1]) {
58	                return entry.getKey();
59	            }
60	        }
61	        return null;
62	    }
63	}
